// @FIGURE_CODE_BEGIN
// Coaxial cylindrical capacitor, axis along X, near end x=-4, far end x=+4.
//  - inner conductor  → CylinderGeometry(R1=1, len 8) light steel blue, rotated to X
//  - outer shell      → open CylinderGeometry(R2=2) translucent #aab4d4 + rim rings
//  - Gaussian surface → 2 dashed orange rings (LineDashedMaterial) + 2 dashed rails
//  - charge glyphs    → canvas sprites '+' / '−'
//  - E arrows         → 8 red arrows in near face plane, R1 → r
//  - far-end fan      → 3 black arrows R1, r, R2
//  - region highlight → translucent cylinder band per region
const R1 = 1.0, R2 = 2.0, LEN = 8, XNEAR = -LEN / 2, XFAR = LEN / 2;

/* ── Conductors ── */
const innerMat = new THREE.MeshPhongMaterial({ color: 0xb0c4de });
const inner = new THREE.Mesh(new THREE.CylinderGeometry(R1, R1, LEN, 48), innerMat);
inner.rotation.z = Math.PI / 2;
scene.add(inner);

const shellMat = new THREE.MeshPhongMaterial({
  color: 0xaab4d4, transparent: true, opacity: 0.3, side: THREE.DoubleSide, depthWrite: false
});
const shell = new THREE.Mesh(new THREE.CylinderGeometry(R2, R2, LEN, 64, 1, true), shellMat);
shell.rotation.z = Math.PI / 2;
scene.add(shell);
// near + far rims of outer shell
for (const x of [XNEAR, XFAR]) {
  const rim = new THREE.Mesh(new THREE.RingGeometry(R2 - 0.16, R2, 64), shellMat);
  rim.position.x = x; rim.rotation.y = Math.PI / 2;
  scene.add(rim);
  const edge = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(
      Array.from({ length: 64 }, (_, i) => {
        const a = i / 64 * Math.PI * 2;
        return new THREE.Vector3(x, R2 * Math.cos(a), R2 * Math.sin(a));
      })),
    new THREE.LineBasicMaterial({ color: 0x8891b8, transparent: true, opacity: 0.6 }));
  scene.add(edge);
}

/* ── Axis ── */
scene.add(new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(XNEAR - 0.6, 0, 0), new THREE.Vector3(XFAR + 0.9, 0, 0)]),
  new THREE.LineDashedMaterial({ color: 0x666666, dashSize: 0.25, gapSize: 0.18 })));
scene.children[scene.children.length - 1].computeLineDistances();

/* ── Lighting ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dl = new THREE.DirectionalLight(0xffffff, 0.7);
dl.position.set(2, 4, 5);
scene.add(dl);

/* ── Charge glyph sprites ── */
function glyphSprite(txt, size = 0.28, color = '#1a1a3a') {
  const cv = document.createElement('canvas'); cv.width = cv.height = 64;
  const g = cv.getContext('2d');
  g.font = 'bold 52px sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillStyle = color; g.fillText(txt, 32, 34);
  const m = new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(cv), transparent: true });
  const s = new THREE.Sprite(m); s.scale.set(size, size, 1);
  return s;
}
// '+' on inner near cap (cluster) and scattered along wall
const plusPts = [];
for (let i = 0; i < 9; i++) {
  const a = i * 0.7 + 0.2, rr = 0.25 + (i % 3) * 0.3;
  plusPts.push(new THREE.Vector3(XNEAR - 0.01, rr * Math.cos(a), rr * Math.sin(a)));
}
for (let i = 0; i < 10; i++) {
  const a = i * 2.4, x = XNEAR + 1 + i * 0.75;
  plusPts.push(new THREE.Vector3(x, R1 * Math.cos(a) * 1.02, R1 * Math.sin(a) * 1.02));
}
plusPts.forEach(p => { const s = glyphSprite('+'); s.position.copy(p); scene.add(s); });
// '−' along outer shell length and around near rim
for (let i = 0; i < 12; i++) {
  const a = i * 1.9, x = XNEAR + 0.4 + i * 0.65;
  const s = glyphSprite('−', 0.3, '#1a1a3a');
  s.position.set(x, R2 * Math.cos(a) * 1.04, R2 * Math.sin(a) * 1.04);
  scene.add(s);
}
for (let i = 0; i < 8; i++) {
  const a = i / 8 * Math.PI * 2 + 0.3;
  const s = glyphSprite('−', 0.3, '#1a1a3a');
  s.position.set(XNEAR - 0.02, (R2 - 0.08) * Math.cos(a), (R2 - 0.08) * Math.sin(a));
  scene.add(s);
}

/* ── Gaussian surface (reactive) ── */
const gaussMat = new THREE.LineDashedMaterial({ color: 0xe8912d, dashSize: 0.22, gapSize: 0.14 });
const gaussGroup = new THREE.Group();
scene.add(gaussGroup);
function buildGaussian(r) {
  while (gaussGroup.children.length) {
    const c = gaussGroup.children.pop();
    c.geometry.dispose(); gaussGroup.remove(c);
  }
  const circle = (x) => {
    const pts = Array.from({ length: 97 }, (_, i) => {
      const a = i / 96 * Math.PI * 2;
      return new THREE.Vector3(x, r * Math.cos(a), r * Math.sin(a));
    });
    const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), gaussMat);
    l.computeLineDistances(); return l;
  };
  gaussGroup.add(circle(XNEAR), circle(XFAR));
  for (const sgn of [1, -1]) {
    const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(XNEAR, sgn * r, 0), new THREE.Vector3(XFAR, sgn * r, 0)]), gaussMat);
    l.computeLineDistances(); gaussGroup.add(l);
  }
}

/* ── E-field arrows at near face ── */
const eGroup = new THREE.Group();
scene.add(eGroup);
function buildE(r, inGap) {
  while (eGroup.children.length) {
    const c = eGroup.children.pop();
    c.traverse(o => o.geometry?.dispose?.()); eGroup.remove(c);
  }
  if (!inGap) return;
  const len = Math.max(r - R1, 0.05);
  for (let i = 0; i < 8; i++) {
    const a = i / 8 * Math.PI * 2;
    const dir = new THREE.Vector3(0, Math.cos(a), Math.sin(a));
    const arr = new THREE.ArrowHelper(dir, new THREE.Vector3(XNEAR - 0.03, R1 * Math.cos(a), R1 * Math.sin(a)),
      len, 0xcc2222, Math.min(0.22, len * 0.4), 0.12);
    eGroup.add(arr);
  }
}

/* ── Far-end radius fan ── */
const fanGroup = new THREE.Group();
scene.add(fanGroup);
function buildFan(r) {
  while (fanGroup.children.length) {
    const c = fanGroup.children.pop();
    c.traverse(o => o.geometry?.dispose?.()); fanGroup.remove(c);
  }
  const mk = (len, a) => {
    const dir = new THREE.Vector3(0, Math.cos(a), Math.sin(a));
    const arr = new THREE.ArrowHelper(dir, new THREE.Vector3(XFAR + 0.02, 0, 0),
      len, 0x222222, 0.14, 0.09);
    fanGroup.add(arr);
    return arr;
  };
  mk(R1, Math.PI / 2);            // R1 up
  mk(r, Math.PI / 2 - 0.7);       // r
  mk(R2, Math.PI / 2 - 1.5);      // R2
}

/* ── Region highlight bands ── */
function band(rIn, rOut, color) {
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(rOut, rOut, LEN, 64, 1, true),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.14, side: THREE.DoubleSide, depthWrite: false }));
  m.rotation.z = Math.PI / 2;
  return m;
}
const bandInner = band(0.01, R1, 0x4da3ff);
const bandGap = band(R1, R2, 0x66cc88);
const bandOuter = band(R2, R2 + 0.55, 0xcc77dd);
scene.add(bandInner, bandGap, bandOuter);

/* ── State / controls ── */
let curR = 1.5, curRegion = 'gap';
const rVal = document.getElementById('rVal');
const info = document.getElementById('regionInfo');
const fanLabels = [];
function fanLabel(txt, len, a) {
  const e = addLabel(txt, new THREE.Vector3(XFAR + 0.02, (len + 0.15) * Math.cos(a), (len + 0.15) * Math.sin(a)), { bold: true });
  fanLabels.push(e);
}
function rebuildFanLabels(r) {
  fanLabels.forEach(e => { e.div.remove(); _labels.splice(_labels.indexOf(e), 1); });
  fanLabels.length = 0;
  fanLabel('R₁', R1, Math.PI / 2);
  fanLabel('r', r, Math.PI / 2 - 0.7);
  fanLabel('R₂', R2, Math.PI / 2 - 1.5);
}

function applyState() {
  const inGap = curRegion === 'gap';
  buildGaussian(curR);
  buildE(curR, inGap);
  buildFan(curR);
  rebuildFanLabels(curR);
  bandInner.visible = curRegion === 'inner';
  bandGap.visible = curRegion === 'gap';
  bandOuter.visible = curRegion === 'outer';
  rVal.textContent = curR.toFixed(2);
  document.querySelectorAll('.regionBtn').forEach(b =>
    b.classList.toggle('active', b.dataset.region === curRegion));
  info.innerHTML = curRegion === 'gap'
    ? 'E = λ/(2πε₀r) in the gap; the surface encloses +Q. Arrows shrink as 1/r.'
    : curRegion === 'inner'
      ? 'Inside the conductor the enclosed charge is 0 → E = 0.'
      : 'Outside, the surface encloses +Q and −Q → net 0, so E = 0.';
}
document.getElementById('gaussianRadius').addEventListener('input', e => {
  curR = parseFloat(e.target.value);
  curRegion = curR < R1 + 0.001 ? 'inner' : curR > R2 - 0.001 ? 'outer' : 'gap';
  applyState();
});
document.querySelectorAll('.regionBtn').forEach(b => b.addEventListener('click', () => {
  curRegion = b.dataset.region;
  if (curRegion === 'inner') curR = R1;
  else if (curRegion === 'outer') curR = R2;
  else if (curR <= R1 || curR >= R2) curR = 1.5;
  document.getElementById('gaussianRadius').value = curR;
  applyState();
}));

/* ── Demo steps ── */
const STEPS = [
  { r: 1.5, region: 'gap', title: 'Surface midway in the gap', body: 'With r midway between R1 and R2, the dashed cylinder encloses only the inner conductor\'s +Q. Red E arrows pierce the surface radially, uniform all around.' },
  { r: 1.95, region: 'gap', title: 'Push r toward R₂', body: 'Enclosed charge is unchanged, but the E arrows shorten — E = λ/(2πε₀r) decreases as 1/r while flux stays constant.' },
  { r: R1, region: 'inner', title: 'Inside the conductor', body: 'r < R1: no charge is enclosed and the E arrows vanish — the field inside a conductor is zero.' },
  { r: R2, region: 'outer', title: 'Outside both cylinders', body: 'r > R2: the surface encloses +Q and −Q, net zero, so E = 0 — field lives only in the gap.' },
];
function goToStep(i) {
  const s = STEPS[i];
  curR = s.r; curRegion = s.region;
  document.getElementById('gaussianRadius').value = curR;
  applyState();
  showPopup(s.title, s.body);
}
document.querySelectorAll('.stepBtn').forEach(b =>
  b.addEventListener('click', () => goToStep(parseInt(b.dataset.step))));

applyState();

/* ── Camera + static labels ── */
setCameraView({ projection: 'perspective', azimuthDeg: 20, elevationDeg: 8, rollDeg: 0, heightFraction: 0.65 });

addLabel('E', new THREE.Vector3(XNEAR - 0.15, R1 + 0.35, 0), { color: '#cc2222', bold: true, fontSize: '15px' });
addLabel('Gaussian surface', new THREE.Vector3(0.8, R2 + 0.75, 0), { color: '#b06010', bold: true, fontSize: '14px' });
addLabel('+Q (inner conductor)', new THREE.Vector3(XNEAR - 0.2, -R1 - 0.4, 0), { fontSize: '12px', color: '#1a1a3a' });
addLabel('−Q (outer shell)', new THREE.Vector3(2.2, -R2 - 0.35, 0), { fontSize: '12px', color: '#1a1a3a' });

registerInteractive(gaussGroup, { title: 'Gaussian surface', body: 'Imaginary coaxial cylinder of radius r. Enclosed charge = +Q only for R1 < r < R2.', tooltip: 'Gaussian surface' });
registerInteractive(inner, { title: 'Inner conductor (R₁)', body: 'Carries +Q on its surface. E = 0 inside the metal.', tooltip: 'Inner conductor' });
registerInteractive(shell, { title: 'Outer shell (R₂)', body: 'Carries −Q on its inner wall. Field vanishes outside.', tooltip: 'Outer shell' });
